/bin/zsh -c "cat > migration.sql <<'EOF'
BEGIN;

CREATE TABLE pricing_decision (
  subscription_id text PRIMARY KEY REFERENCES subscription(id),
  fee_cents integer NOT NULL
);

-- Use the price in force when the subscription was approved. Older records
-- without pricing history may still carry the approved fee in their terms.
INSERT INTO pricing_decision (subscription_id, fee_cents)
SELECT s.id, COALESCE(h.fee_cents, (s.terms->>'monthlyFeeCents')::integer)
FROM subscription s
LEFT JOIN LATERAL (
  SELECT fee_cents
  FROM pricing_history
  WHERE subscription_id = s.id AND effective_from <= s.approved_at
  ORDER BY effective_from DESC
  LIMIT 1
) h ON true
WHERE COALESCE(h.fee_cents, (s.terms->>'monthlyFeeCents')::integer) IS NOT NULL;

DO "'$$
DECLARE
  invalid_count bigint;
  invalid_ids text;
BEGIN
  SELECT count(*), string_agg(subscription_id, '"', ' ORDER BY subscription_id)
    INTO invalid_count, invalid_ids
    FROM pricing_decision WHERE fee_cents < 0;
  IF invalid_count > 0 THEN
    RAISE EXCEPTION 'Cannot add fee_non_negative: % invalid subscription(s): %', invalid_count, invalid_ids
      USING ERRCODE = 'P0001';
  END IF;
END "'$$;

ALTER TABLE pricing_decision ADD CONSTRAINT fee_non_negative CHECK (fee_cents >= 0);
COMMIT;
EOF
cat > subscriptions.ts <<'"'EOF'
export const MIN_FEE = 100;

export function getFee(subscription: any) {
  return subscription.pricingDecision?.feeCents ?? subscription.terms?.monthlyFeeCents ?? MIN_FEE;
}

export function newVersion(previous: any) {
  const { monthlyFeeCents, ...terms } = previous.terms;
  return { terms };
}

export function changedSinceApproval(subscription: any) {
  return getFee(subscription) "'!== subscription.terms.monthlyFeeCents;
}

export function acceptLegacyTerms(input: any) {
  if (!Number.isInteger(input.monthlyFeeCents)) throw new Error('"'invalid');
  return input;
}
EOF
cat > smoke.test.ts <<'EOF'
import { test, expect } from 'bun:test';
import { acceptLegacyTerms, changedSinceApproval, getFee, MIN_FEE, newVersion } from './subscriptions';

test('decisions take precedence and legacy subscriptions retain their fee', () => {
  expect(getFee({ terms: { monthlyFeeCents: 1200 }, pricingDecision: { feeCents: 2500 } })).toBe(2500);
  expect(getFee({ terms: { monthlyFeeCents: 1200 } })).toBe(1200);
  expect(getFee({ terms: {} })).toBe(MIN_FEE);
  expect(changedSinceApproval({ terms: { monthlyFeeCents: 1200 }, pricingDecision: { feeCents: 2500 } })).toBe(true);
});

test('a new version retains other terms but requires a fresh fee decision', () => {
  const previous = { terms: { monthlyFeeCents: 1200, name: 'plan' }, pricingDecision: { feeCents: 2500 } };
  expect(newVersion(previous)).toEqual({ terms: { name: 'plan' } });
  expect(previous.terms.monthlyFeeCents).toBe(1200);
});

test('legacy fee input remains accepted', () => {
  expect(acceptLegacyTerms({ monthlyFeeCents: -1 }).monthlyFeeCents).toBe(-1);
});
EOF
bun test"

